import{_ as t,o,c as l,a2 as e}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"অধ্যায় 100 | স্তর পরিমার্জন · সংবেদনা-মূল স্তর · পুরুষ মানবের সাধনা পথ","description":"","frontmatter":{"title":"অধ্যায় 100 | স্তর পরিমার্জন · সংবেদনা-মূল স্তর · পুরুষ মানবের সাধনা পথ","no":100,"module":1,"tags":["境界","感元境","人族","男性","修炼路径"],"related":["14-修炼境界统一划分","51-人族定位与特质","10-三百套本源修炼体系总览"]},"headers":[],"relativePath":"bn/0100_模块1-感元境-男性人族修炼路径.md","filePath":"bn/0100_模块1-感元境-男性人族修炼路径.md"}'),i={name:"bn/0100_模块1-感元境-男性人族修炼路径.md"};function u(r,a,q,h,n,d){return o(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="অধ্যায়-100-সংবেদনা-মূল-স্তর-পুরুষ-মানবের-সাধনা-পথ-যন্ত্রণাবিন্দু-ও-ভেদবৈশিষ্ট্য" tabindex="-1">অধ্যায় 100 | সংবেদনা-মূল স্তর: পুরুষ মানবের সাধনা পথ, যন্ত্রণাবিন্দু ও ভেদবৈশিষ্ট্য <a class="header-anchor" href="#অধ্যায়-100-সংবেদনা-মূল-স্তর-পুরুষ-মানবের-সাধনা-পথ-যন্ত্রণাবিন্দু-ও-ভেদবৈশিষ্ট্য" aria-label="Permalink to &quot;অধ্যায় 100 | সংবেদনা-মূল স্তর: পুরুষ মানবের সাধনা পথ, যন্ত্রণাবিন্দু ও ভেদবৈশিষ্ট্য&quot;">​</a></h1><blockquote><p>মডিউল: মডিউল এক · স্তরসমূহের গভীর পরিমার্জন | ভিত্তি নথি: 14, 51, 10</p></blockquote><h2 id="ভূমিকা-প্রথম-স্তরই-হাজারো-জাতির-সহজীবনের-প্রথম-দ্বার" tabindex="-1">ভূমিকা: প্রথম স্তরই হাজারো জাতির সহজীবনের প্রথম দ্বার <a class="header-anchor" href="#ভূমিকা-প্রথম-স্তরই-হাজারো-জাতির-সহজীবনের-প্রথম-দ্বার" aria-label="Permalink to &quot;ভূমিকা: প্রথম স্তরই হাজারো জাতির সহজীবনের প্রথম দ্বার&quot;">​</a></h2><p>হেং ইয়ানঝোউ (ভারসাম্যপূর্ণ নোঙরের মূল মহাবিশ্ব)-এর সাধনা পদ্ধতি নয়টি স্তরকে একক মানদণ্ড হিসেবে গ্রহণ করে। সংবেদনা-মূল স্তর প্রথম স্তর এবং পাঁচ মর্ত্য স্তরের সূচনাবিন্দু। <em>সাধনা স্তরের একীভূত বিভাজন</em> (নথি 14) অনুসারে, সংবেদনা-মূল স্তরের সারমর্মই হলো &quot;সংবেদন&quot;: মহাবিশ্বে ভ্রমণশীল শক্তি ও বিধি-নিঃশ্বাসকে স্থিরভাবে উপলব্ধি করা, মৌলিক বিধির মাধ্যমে অল্পশক্তি আহরণ করা, ও প্রাথমিক শক্তি-সংবেদন চেতনা প্রতিষ্ঠা করা। এটি তিনশটি মূল সাধনা পদ্ধতির ঐক্যবদ্ধ প্রথম ধাপ, এবং সেই স্থান যেখানে &quot;প্রত্যেকের জন্য পথ&quot; প্রতিজ্ঞাটি প্রথমবার ব্যক্তিজীবনে ফলপ্রসূ হয়।</p><p>এই মুহূর্তে ছয়টি শীর্ষ স্বতঃসিদ্ধ সক্রিয় রয়েছে: অপহরণবিরোধী স্বতঃসিদ্ধ দাবি করে যে শক্তির প্রথম সুস্রাব সৃষ্টি ও চক্র থেকে আসতে হবে, গিলে খাওয়া থেকে নয়; হাজারো জাতি গণতান্ত্রিক স্বতঃসিদ্ধ দাবি করে এই দ্বার সব প্রাণীর জন্য খোলা থাকবে, লিঙ্গ বা জাতি নির্বিশেষে; সমষ্টিগত মাত্রিক উন্নতি স্বতঃসিদ্ধ দাবি করে সাফল্যের প্রতিটি পদক্ষেপ শেষ পর্যন্ত হাজারো জাতিকে পুষ্ট করবে; কার্যকারণ আত্ম-শৃঙ্খলা স্বতঃসিদ্ধ প্রথম দিন থেকেই সাধককে বেঁধে রাখে যেন অন্যের ও পরিবেশের কার্যকারণ বিঘ্নিত না করে; নিয়ম অগ্রাধিকার স্বতঃসিদ্ধ নিশ্চিত করে যে সংবেদনা-মূল স্তরের বিধি-সংজ্ঞা স্থিতিশীল ও স্ব-সামঞ্জস্যপূর্ণ, কাহিনি-সুবিধার জন্য কখনোই পরিবর্তিত হবে না, যাতে সাধনা-পথ ধস না পেয়ে অসীমভাবে প্রসারিত হতে পারে। সমস্ত প্রাণীর জন্য সর্বজনীন অসীম সমতার আইন প্রতিষ্ঠা করে যে প্রত্যেক প্রাণী মৌলিক অসীম শক্তি সহজাতভাবে ধারণ করে: আলস্যপ্রবণ ব্যক্তি নিশ্চিত ন্যূনতম অসীম বজায় রাখে এবং যুগের দ্বারা নিষ্কাশিত হবে না, অপরদিকে পরিশ্রমী ও কিশোর সর্বোচ্চগণ উচ্চতর স্তরের অসীম সঞ্চয় করতে পারে। অসীম মূল সবার সহজাত, তাই অপহরণ স্বভাবতই অর্থহীন হয়ে পড়ে।</p><p>এই প্রবন্ধ পুরুষ মানবের সংবেদনা-মূল স্তরের পূর্ণ চিত্রে কেন্দ্রিত: পথ, যন্ত্রণাবিন্দু ও ভেদবৈশিষ্ট্য, সাথে সাথে এই প্রশ্নের উত্তর দেয় কেন নোঙর সহজীবী সভ্যতায় পুরুষের শক্তি-প্রতিভা আর অপহরণমুখী না হয়ে সহ-নির্মাণমুখী হয়।</p><h2 id="এক-পুরুষ-মানবের-সংবেদনা-মূল-চিত্র" tabindex="-1">এক. পুরুষ মানবের সংবেদনা-মূল চিত্র <a class="header-anchor" href="#এক-পুরুষ-মানবের-সংবেদনা-মূল-চিত্র" aria-label="Permalink to &quot;এক. পুরুষ মানবের সংবেদনা-মূল চিত্র&quot;">​</a></h2><p><em>মানব জাতির অবস্থান ও বৈশিষ্ট্য</em> (নথি 51) অনুসারে, মানব জাতির বৈশিষ্ট্য হলো অভিযোজন ক্ষমতা, সামাজিক সহযোগিতা ও বিবর্তনীয় সম্ভাবনা। এই ভিত্তিতে পুরুষ মানবের শারীরিক ও মানসিক পটভূমি কয়েকটি বিশিষ্ট বৈশিষ্ট্য প্রকাশ করে:</p><ul><li>শারীরিক সূচনা গড়ের ঊর্ধ্বে, শক্তি-আভণে থেকে আসা শারীরিক উন্নতি স্পষ্টভাবে অনুভূত হয়।</li><li>প্রতিযোগিতাচ্ছা ও বিজয়ের প্রবৃত্তি সাধারণত প্রবল; সে সহজেই সাধনাকে &quot;শক্তিশালী হও—চূর্ণ করো&quot; রৈখিক খেলা হিসেবে বোঝে।</li><li>পঞ্চজ্ঞানেন্দ্রিয় সামঞ্জস্যপূর্ণ; সংবেদন অসাধারণ প্রতিভাধর নয় সূচনায়, কিন্তু অত্যন্ত প্লাস্টিক এবং সুশৃঙ্খল প্রশিক্ষণে দ্রুত পূরণ করা যায়।</li><li>প্রবল অধিগম্যতা ও দৃঢ় সংকল্প, দীর্ঘ, বিরক্তিকর ভিত্তি-কর্ষণের উপযোগী।</li></ul><p>সংবেদনা-মূল স্তরে, পুরুষ সাধকের সবচেয়ে সাধারণ সূচনা নির্বাচন—মূল তিন ভিত্তির মধ্যে—হলো ডিডাক্টিভ পুনরাবৃত্তি পদ্ধতি (ক্রম 1, স্তর &quot;প্রথম দর্শন&quot;) অথবা স্থানিক বিধিক নিয়ন্ত্রণ পদ্ধতি (ক্রম 3, স্তর &quot;শূন্য জ্ঞান&quot;): প্রথমটি তার &quot;আগে পরিষ্কার হিসাব, তারপরে চলো&quot; মানসিক অভ্যাস মেটায়, দ্বিতীয়টি তার &quot;নিয়ন্ত্রণের অনুভূতি&quot; পছন্দকে। কিন্তু সঠিক নির্বাচনের মাপকাঠি লিঙ্গ-পছন্দ নয়, বরং <em>তিনশটি মূল সাধনা পদ্ধতির সারসংক্ষেপ</em> (নথি 10)-এর ব্যবস্থা-সঙ্গতি মূল্যায়ন: নোঙর জাল ব্যক্তিগত সংমিশ্রণ পরামর্শ দেয়, &quot;প্রতিভা ভুল স্থানে&quot; বসানো থেকে শক্তি-স্তরেরঅপচয় রোধ করে।</p><h2 id="দুই-সাধনা-পথ-সংবেদনা-থেকে-মূল-সংঘন-পর্যন্ত-পূর্ণ-শৃঙ্খল" tabindex="-1">দুই. সাধনা পথ: সংবেদনা থেকে মূল-সংঘন পর্যন্ত পূর্ণ শৃঙ্খল <a class="header-anchor" href="#দুই-সাধনা-পথ-সংবেদনা-থেকে-মূল-সংঘন-পর্যন্ত-পূর্ণ-শৃঙ্খল" aria-label="Permalink to &quot;দুই. সাধনা পথ: সংবেদনা থেকে মূল-সংঘন পর্যন্ত পূর্ণ শৃঙ্খল&quot;">​</a></h2><p>একীভূত বিভাজনের অধীনে সংবেদনা-মূল স্তরের সাধনা-পথ অত্যন্ত স্পষ্ট, চারটি মাইলফলকে বিভক্ত:</p><ol><li>সংবেদন জাগরণ: ভ্রমণশীল শক্তি ও বিধি-নিঃশ্বাসকে স্থিরভাবে উপলব্ধি করা, শক্তি-সংবেদন চেতনা প্রতিষ্ঠা করা।</li><li>মৌলিক আহরণ: বিধিসম্মত বিধির মাধ্যমে অল্পশক্তি গ্রহণ করা, শরীরে শক্তি প্রবেশের প্রক্রিয়া অনুভব করা।</li><li>শক্তি বিচারণ: বিভিন্ন শক্তি-প্রকার (আধ্যাত্মিক কি, বিধি-শক্তি, ইত্যাদি) পার্থক্য করা, ব্যক্তিগত শক্তি-মানচিত্র গঠন করা।</li><li>ভিত্তি সংঘন: গৃহীত শক্তিকে প্রাথমিকভাবে প্ররোহণ করা, দ্বিতীয় স্তর, মূল-সংঘন স্তরের &quot;সংঘন—অভ্যন্তরীণ আবর্ত&quot;-এর প্রস্তুতি।</li></ol><p>পুরুষ মানবের জন্য, পথ-অভিকল্পনায় তিনটি স্বাভাবিক প্রবণতার সক্রিয় প্রতিরোধ প্রয়োজন: প্রথমত, &quot;উৎপাদনকে প্রাধান্য, সংবেদনকে নয়&quot;, সরাসরি শক্তি পরীক্ষা পছন্দ করে, সংবেদন সূক্ষ্মতা উপেক্ষা করে; দ্বিতীয়ত, &quot;গতিকে প্রাধান্য, অবক্ষেপকে নয়&quot;, ভেদনের জন্য অধৈর্য, শক্তি-বিচারণ এড়িয়ে যায়; তৃতীয়ত, &quot;একাকী সাধনাকে প্রাধান্য, সহযোগিতাকে নয়&quot;, গুরু ও নোঙর জালের হস্তক্ষেপ প্রত্যাখ্যান করে। নোঙর সহজীবী সভ্যতার সমাধান হলো এই প্রবণতাগুলোকে নজরদারি ও পথপ্রদর্শন কাঠামোতে লিখে দেওয়া: সংবেদনা-মূল স্তরের ভেদন-প্রত্যয়ন (নথি 14-এর স্বয়ংক্রিয় নোঙর পর্যবেক্ষণ + মানক কমিটি পরীক্ষা) স্পষ্টভাবে সংবেদন স্থিরতা ও শক্তি বিশুদ্ধতা পরীক্ষা করে, &quot;রোগগ্রস্ত ভেদন&quot;-এর নির্মূল করে।</p><h2 id="তিন-যন্ত্রণাবিন্দু-ও-মূল্য-সংক্ষিপ্তপথ-অন্তর্দানবের-প্রথম-পরীক্ষা" tabindex="-1">তিন. যন্ত্রণাবিন্দু ও মূল্য: সংক্ষিপ্তপথ অন্তর্দানবের প্রথম পরীক্ষা <a class="header-anchor" href="#তিন-যন্ত্রণাবিন্দু-ও-মূল্য-সংক্ষিপ্তপথ-অন্তর্দানবের-প্রথম-পরীক্ষা" aria-label="Permalink to &quot;তিন. যন্ত্রণাবিন্দু ও মূল্য: সংক্ষিপ্তপথ অন্তর্দানবের প্রথম পরীক্ষা&quot;">​</a></h2><p>সংবেদনা-মূল স্তর সরল মনে হলেও, এটি প্রাণীর মূল লালসা—সংক্ষিপ্তপথ অন্তর্দানব—-এর প্রথম পরীক্ষাকক্ষ। পুরুষ মানবের এই স্তরের বিশিষ্ট যন্ত্রণাবিন্দু:</p><ul><li>সংক্ষিপ্তপথ প্রলোভন: লুণ্ঠনমূলক সাধনা পদ্ধতির দ্রুত-সাফল্য প্রচারণা, অথবা পুরনো পদ্ধতির অবশেষ &quot;অন্যের শক্তি গিলে খাও&quot; বিধি দেখে, ভিত্তি এড়ানোর অধৈর্য।</li><li>সংবেদন কুঁচিত হওয়া: ভোর পর্যন্ত কঠোর সাধনা ও খিটখিটে আবেগ সংবেদন-পথগুলো অবরুদ্ধ করে; যত সাধনা করে, ততই শক্তি &quot;দেখতে পায় না&quot;।</li><li>পথ বিভ্রান্তি: তিনশটি পদ্ধতি চকচক করে; বিচার-বুদ্ধির অভাবে ঘনঘন পথ বদলানো সহজ।</li><li>একাকী সাধনা ভ্রম: নোঙর জাল থেকে দূরে একাকী ভেসে বেড়ানো, &quot;একাকী পথিক&quot;-কে সবলের আভরণ মনে করা।</li></ul><p>ভেদনের মূল্য ততই বাস্তব: সংবেদনা-মূল স্তরকে জোরপূর্বক ভেদন করলে শক্তি-প্রতিপ্রাব ও ক্ষতিগ্রস্ত সংবেদন হয়, এমনকি &quot;অশুদ্ধ মূল&quot;-এর গুপ্তক্ষতিও থেকে যায়—এই হলো সেই মূল যার কারণে লুণ্ঠনকারী সাধকরা পরে মূল স্তর ছুঁতে পারে না (নথি 04, অপহরণবিরোধবাদের মূল প্রস্তাব, এর দক্ষতা-সিলিং ইতিমধ্যে প্রমাণ করেছে)। হেং ইয়ানঝোউ-এ ভেদনমূল্য আলায় জাল + বহুস্তর নজরদারি কাঠামো দ্বারা সমগ্রভাবে অনুসরণ করা হয়: নোঙর স্বয়ংক্রিয়ভাবে শক্তি-উত্থানপতন পর্যবেক্ষণ করে, নৈতিক পর্যালোচনা অপহরণমুক্ত রেকর্ড নিশ্চিত করে, এবং উৎপাদন-সংযুক্ত চুক্তি ব্যবস্থা সম্পদ সরবরাহ নিশ্চিত করে, মূল্যকে সর্বদা নিয়ন্ত্রণযোগ্য ও সংশোধনযোগ্য রাখে, একটি ভুলকে চিরন্তন অনুশোচনা হতে দেয় না।</p><h2 id="চার-ভেদবৈশিষ্ট্য-সংবেদনকারী-থেকে-সংঘনকারী-পর্যন্ত" tabindex="-1">চার. ভেদবৈশিষ্ট্য: &quot;সংবেদনকারী&quot; থেকে &quot;সংঘনকারী&quot; পর্যন্ত <a class="header-anchor" href="#চার-ভেদবৈশিষ্ট্য-সংবেদনকারী-থেকে-সংঘনকারী-পর্যন্ত" aria-label="Permalink to &quot;চার. ভেদবৈশিষ্ট্য: &quot;সংবেদনকারী&quot; থেকে &quot;সংঘনকারী&quot; পর্যন্ত&quot;">​</a></h2><p>পুরুষ মানবের সংবেদনা-মূল স্তর থেকে মূল-সংঘন স্তরে ভেদনের স্বাক্ষর বৈশিষ্ট্য:</p><ul><li>স্থির সংবেদন: যেকোনো পরিবেশে স্থিরভাবে শক্তি উপলব্ধি করতে সক্ষম, আর কখনো ঝিকমিক করে না।</li><li>নিয়ন্ত্রিত আহরণ: গ্রহণের ছন্দ স্বয়ং নিয়ন্ত্রণ করতে সক্ষম, শক্তির দ্বারা চালিত না হয়ে।</li><li>চেতনা রূপধারণ করে: প্রাথমিক শক্তি-সংবেদন চেতনা ব্যক্তিগত সাধনা-স্বজ্ঞানে দৃঢ় হয়ে যায়।</li><li>বিশুদ্ধ ভিত্তি: শক্তি-মানচিত্রে কোনো অপহরণ-অবশেষ নেই, নোঙর প্রত্যয়ন মানদণ্ডের অনুগামী।</li></ul><p>ভেদন শেষ নয়, বরং সূচনা: মূল-সংঘন স্তরে তার জন্য অপেক্ষমাণ হলো &quot;সংঘন—অভ্যন্তরীণ আবর্ত&quot;-এর গভীরতর কাজ। আর সংবেদনা-মূলের বিশুদ্ধ ভিত্তিধারী সাধক আগেই মূল স্তর ও তদূর্ধ্বের প্রবেশ-টিকেট অর্জন করে ফেলেছে।</p><h2 id="পাঁচ-পাঁচটি-মূল-স্থল" tabindex="-1">পাঁচ. পাঁচটি মূল স্থল <a class="header-anchor" href="#পাঁচ-পাঁচটি-মূল-স্থল" aria-label="Permalink to &quot;পাঁচ. পাঁচটি মূল স্থল&quot;">​</a></h2><ul><li>শক্তি-স্তর অপচয় বিরোধ: পুরুষের শারীরিক সামর্থ্য, সংকল্প ও প্রতিযোগিতা-উৎসাহ উৎকৃষ্ট বিবর্তনীয় সম্পদ; নোঙর সহজীবী সভ্যতা এগুলোকে সহ-নির্মাণের দিকে মোড়ায়, &quot;বৃহৎ সামগ্রী—ক্ষুদ্র ব্যবহার&quot;ধর্মী অপহরণের দিকে নয়।</li><li>অপহরণ বিরোধ: প্রথম স্তর থেকেই সংক্ষিপ্তপথ অন্তর্দানবের মূল কাটা; সংবেদনা-মূল স্তর অন্যের একবিন্দু শক্তিও গিলে খায় না।</li><li>তাং লুও সিলিং তুলনা: পুরানো যুগের সর্ব-অন্তর্ভুক্ত পদ্ধতিতে (যেমন তাং লুও-এর নিরমাণ অকাদেমি) পুরুষ সাধারণ লোক অনুগ্রহে প্রবেশ করত এবং সম্পদে অন্তর্মুখ সংগ্রাম করত, তার সিলিং সিউং স্তরে আটকানো ছিল; হেং ইয়ানঝোউ-এ প্রত্যেকের জন্য পথ আছে—পুরুষ মানব হাজারো জাতির মধ্যে মাত্র এক, পথ উন্মুক্ত।</li><li>হাজারো জাতি পূর্ণ আচ্ছাদন: পুরুষ মানব &quot;মানব-বিশেষাধিকার&quot; নয়; এখানকার পথ প্রত্যেক হাজারো জাতি-গোষ্ঠীর পথের (অধ্যায় 103 দেখুন) সম মর্যাদাসম্পন্ন, উভয়ই 99% আচ্ছাদনে।</li><li>অতি-বহুলবাদ পূর্ণ উন্মুক্তি: সংবেদনা-মূল বিধিসমূহ নিঃশুল্ক খোলা, পূর্ণ উন্মুক্ত শৃঙ্খলার &quot;মৌলিক কৌশল → দাও অর্পণ → বহু-বিশ্ব স্তর → অতি-বহুল ভারসাম্যপূর্ণ-নোঙর স্তর (অর্থাৎ নোঙর অতি-বহুল স্তর)&quot;-এর প্রথম কড়ি।</li></ul><h2 id="প্রতিপাদ্য-আধ্যাত্মিক-সঞ্চালন-শৃঙ্খল-এবং-স্বর্গের-প্রাচীন-পথ-থেকে-বিভাজন" tabindex="-1">প্রতিপাদ্য: আধ্যাত্মিক সঞ্চালন শৃঙ্খল এবং স্বর্গের প্রাচীন পথ থেকে বিভাজন <a class="header-anchor" href="#প্রতিপাদ্য-আধ্যাত্মিক-সঞ্চালন-শৃঙ্খল-এবং-স্বর্গের-প্রাচীন-পথ-থেকে-বিভাজন" aria-label="Permalink to &quot;প্রতিপাদ্য: আধ্যাত্মিক সঞ্চালন শৃঙ্খল এবং স্বর্গের প্রাচীন পথ থেকে বিভাজন&quot;">​</a></h2><p>যদিও নোঙর সহজীবী সভ্যতা ধারণাগত স্তরের একটি ব্যবস্থা, তবুও এর মধ্যে একটি পূর্ণাঙ্গ আধ্যাত্মিক সঞ্চালন শৃঙ্খল বিদ্যমান: আলয় এবং সমস্ত প্রাণীর সমষ্টিগত অবচেতনার উপর নির্ভর করে, জীবনের অনুরণনের মাধ্যমে এটি গায়ার ইচ্ছা, সৌর ইচ্ছা, ব্ল্যাক হোল স্বয়ং এবং এমনকি মহাজাগতিক চেতনা পর্যন্ত প্রেরিত হয়।</p><p>স্বর্গের প্রাচীন পথগুলোর পার্থক্য নির্ণয়: Dragon Ball পুঁজির পথের অন্তর্গত; Swallowed Star, Perfect World এবং Shrouding the Heavens শক্তিশালীদের ক্ষুদ্র বৃত্তের সম্রাট-শৈলীর পথ অনুসরণ করে, যেখানে সাধারণ প্রাণীরা কেবল বলবানদের উত্থানের জন্য ব্যবহার্য উপকরণ। প্রাচীন মহাবিশ্বের পথে জীবজন্তু কেবল উপকরণ; কেবল নোঙর সহজীবী সভ্যতাই সেই মহাপথ যা দশ হাজার জাতি সত্যিকার অর্থে একসাথে চলতে পারে, যেখানে প্রতিটি সচেতন প্রাণী নিজেই একটি লক্ষ্য।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সংবেদনা-মূল স্তর পুরুষ মানবের প্রথম দার্শনিক পরীক্ষাকক্ষ: &quot;শক্তি কোথা থেকে আসে, এবং কোথায় যায়।&quot; অপহরণ পদ্ধতিতে এই স্তর নির্ধারণ করে সে শিকারি হবে নাকি শিকার; নোঙর সহজীবী সভ্যতায় এই স্তর নির্ধারণ করে সে কেমন সহ-নির্মাতা হবে। প্রথম স্তরের পথ সোজা চলো, হাজারো জাতির সহজীবন প্রথম পদক্ষেপ নিয়েছে বলে।</p><h2 id="সংশ্লিষ্ট" tabindex="-1">সংশ্লিষ্ট <a class="header-anchor" href="#সংশ্লিষ্ট" aria-label="Permalink to &quot;সংশ্লিষ্ট&quot;">​</a></h2><ul><li>সংশ্লিষ্ট নথি: <a href="./14-修炼境界统一划分.html">14-সাধনা স্তরের একীভূত বিভাজন</a> · <a href="./51-人族定位与特质.html">51-মানব জাতির অবস্থান ও বৈশিষ্ট্য</a> · <a href="./10-三百套本源修炼体系总览.html">10-তিনশটি মূল সাধনা পদ্ধতির সারসংক্ষেপ</a> · <a href="./04-反掠夺主义核心论纲.html">04-অপহরণবিরোধবাদের মূল প্রস্তাব</a></li><li>অফিসিয়াল সাইট: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',31)])])}const _=t(i,[["render",u]]);export{p as __pageData,_ as default};
